15	
16	const pluralHours = (count: number) => `${count} ${count === 1 ? 'hour' : 'hours'}`
17	
18	function RangeBadge({ range, format }: { range: HourRange; format: TimeFormat }) {
19	  const wraps = range.hours < HOURS_PER_DAY && range.end <= range.start
20	  const label =
21	    range.hours === HOURS_PER_DAY
22	      ? 'All day'
23	      : `${formatHour(range.start, format)} — ${formatHour(range.end, format)}`
24	  return (
25	    <li
26	      className={styles.badge}
27	      data-testid="overlap-range"
28	      title={`${pluralHours(range.hours)}${wraps ? ', continues into the next day' : ''}`}
29	    >
30	      {label}
31	    </li>
32	  )
33	}
34	
35	function Ranges({ ranges, format }: { ranges: HourRange[]; format: TimeFormat }) {
36	  return (
37	    <ul className={styles.badges} aria-label="Overlap windows">
38	      {ranges.map((range) => (
39	        <RangeBadge key={range.start} range={range} format={format} />
40	      ))}
41	    </ul>
42	  )
43	}
44	
45	export function OverlapSummary({ mode, views, summaries, format }: Props) {
46	  if (views.length < 2) {
47	    return (
48	      <p className={styles.note}>
49	        {views.length === 0
50	          ? 'Add a city to get started.'
51	          : 'Add another city to see when your schedules overlap.'}
52	      </p>
53	    )
54	  }
55	
56	  const reference = views[0].city.name
57	
58	  if (mode === 'meeting') {
59	    const summary = summaries[0]
60	    if (!summary) return null
61	
62	    if (summary.hours === 0) {
63	      return (
64	        <section className={`${styles.card} ${styles.warning}`} data-testid="overlap-summary" aria-label="Overlap summary">
65	          <WarningIcon className={styles.icon} size={20} />
66	          <div className={styles.body}>
67	            <p className={styles.headline}>No overlap</p>
68	            <p className={styles.detail}>
69	              There is no hour when every city is awake. Widen the awake window or remove a city.
70	            </p>
71	          </div>
72	        </section>
73	      )
74	    }
75	
76	    return (
77	      <section className={`${styles.card} ${styles.success}`} data-testid="overlap-summary" aria-label="Overlap summary">
78	        <CheckIcon className={styles.icon} size={20} />
79	        <div className={styles.body}>
80	          <p className={styles.headline}>
81	            {pluralHours(summary.hours)} <span className={styles.headlineMuted}>when everyone is awake</span>
82	          </p>
83	          <Ranges ranges={summary.ranges} format={format} />
84	          <p className={styles.detail}>Times in {reference} (reference city).</p>
85	        </div>
86	      </section>
87	    )
88	  }
89	
90	  return (
91	    <section className={`${styles.card} ${styles.column}`} data-testid="overlap-summary" aria-label="Overlap summary">
92	      <p className={styles.headline}>
93	        Overlap with {reference} <span className={styles.headlineMuted}>(reference city)</span>
94	      </p>
95	      <ul className={styles.lines}>
96	        {views.slice(1).map((view, index) => {
97	          const summary = summaries[index]
98	          if (!summary) return null
99	          return (
100	            <li key={view.city.id} className={styles.line} data-testid="overlap-line">
101	              <span className={styles.lineCity}>{view.city.name}</span>
102	              {summary.hours === 0 ? (
103	                <span className={styles.lineWarning}>
104	                  <WarningIcon size={14} />
105	                  No overlap with {reference}
106	                </span>
107	              ) : (
108	                <>
109	                  <span className={styles.lineCount}>{pluralHours(summary.hours)}</span>
110	                  <Ranges ranges={summary.ranges} format={format} />
111	                </>
112	              )}
113	            </li>
114	          )
115	        })}
116	      </ul>
117	      <p className={styles.detail}>Times in {reference}.</p>
118	    </section>
119	  )
120	}
