const page = await browser.getPage("main");
await page.setViewportSize({ width: 1280, height: 900 });
const out = [];
const scenarios = [
  { mode: 'meeting', wake: 7, sleep: 23, ids: ['san-francisco','denpasar','geneva','mumbai','kathmandu','honolulu'] },
  { mode: 'base', wake: 7, sleep: 23, ids: ['san-francisco','denpasar','geneva','mumbai','kathmandu','honolulu'] },
  { mode: 'meeting', wake: 22, sleep: 6, ids: ['tokyo','auckland','sydney','london'] },
  { mode: 'base', wake: 22, sleep: 6, ids: ['new-york','london','tokyo','mumbai'] },
  { mode: 'base', wake: 9, sleep: 9, ids: ['new-york','london','tokyo'] },
];
for (const sc of scenarios) {
  await page.evaluate((sc) => localStorage.setItem('timezone-overlap:v1', JSON.stringify({ cityIds: sc.ids, mode: sc.mode, settings: { wake: sc.wake, sleep: sc.sleep, timeFormat: '24h' } })), sc);
  await page.reload();
  await page.waitForSelector('[data-testid="city-row"]');
  const r = await page.evaluate(async (sc) => {
    const tz = { 'san-francisco':'America/Los_Angeles','denpasar':'Asia/Makassar','geneva':'Europe/Zurich','mumbai':'Asia/Kolkata','kathmandu':'Asia/Kathmandu','honolulu':'Pacific/Honolulu','tokyo':'Asia/Tokyo','auckland':'Pacific/Auckland','sydney':'Australia/Sydney','london':'Europe/London','new-york':'America/New_York' };
    const now = new Date();
    const off = (z) => { const p = new Intl.DateTimeFormat('en-US', { timeZone: z, timeZoneName: 'longOffset' }).formatToParts(now).find((x) => x.type === 'timeZoneName').value; const m = p.match(/GMT([+-])(\d{2}):(\d{2})/); return m ? (m[1] === '-' ? -1 : 1) * (+m[2] * 60 + +m[3]) : 0; };
    const awake = (h) => sc.wake === sc.sleep ? true : sc.wake < sc.sleep ? h >= sc.wake && h < sc.sleep : h >= sc.wake || h < sc.sleep;
    const rows = [...document.querySelectorAll('[data-testid="city-row"]')];
    const refOff = off(tz[sc.ids[0]]);
    const local = (ci, h) => { const m = (((h * 60 + off(tz[sc.ids[ci]]) - refOff) % 1440) + 1440) % 1440; return Math.floor(m / 60); };
    let mismatches = 0; const notes = [];
    for (let h = 0; h < 24; h++) {
      const locals = sc.ids.map((_, ci) => local(ci, h));
      const all = locals.every(awake);
      sc.ids.forEach((_, ci) => {
        const cell = rows[ci].querySelectorAll('[data-testid="hour-cell"]')[h];
        let expected;
        if (!awake(locals[ci])) expected = 'sleeping';
        else if (sc.mode === 'meeting') expected = all ? 'overlap' : 'awake';
        else expected = ci === 0 ? 'awake' : (awake(locals[0]) ? 'overlap' : 'awake');
        const shownHour = parseInt(cell.textContent.trim().slice(0, 2), 10);
        if (cell.dataset.state !== expected || shownHour !== locals[ci]) { mismatches++; if (notes.length < 4) notes.push({ city: sc.ids[ci], h, got: cell.dataset.state, expected, shownHour, local: locals[ci] }); }
      });
    }
    const offsetLabels = rows.map((row) => (row.textContent.match(/UTC[+-]\d+(?::\d+)?/) || [''])[0]);
    const summaries = sc.mode === 'meeting'
      ? [document.querySelector('[data-testid="overlap-summary"]').textContent.replace(/\s+/g, ' ').slice(0, 110)]
      : [...document.querySelectorAll('[data-testid="overlap-line"]')].map((l) => l.textContent.replace(/\s+/g, ' '));
    return { mismatches, notes, offsetLabels, summaries };
  }, sc);
  out.push({ mode: sc.mode, window: `${sc.wake}-${sc.sleep}`, ids: sc.ids.join(','), ...r });
}
console.log(JSON.stringify(out, null, 1));
EOF

