const page = await browser.getPage("main");
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
const six = { cityIds: ['san-francisco','denpasar','geneva','mumbai','kathmandu','honolulu'], mode: 'meeting', settings: { wake: 7, sleep: 23, timeFormat: '12h' } };
const three = { cityIds: ['san-francisco','denpasar','geneva'], mode: 'meeting', settings: { wake: 7, sleep: 23, timeFormat: '12h' } };
const measure = () => page.evaluate(() => {
  const cells = [...document.querySelectorAll('[data-testid="hour-cell"]')];
  const rows = document.querySelectorAll('[data-testid="city-row"]').length;
  const cols = [...document.querySelectorAll('[data-testid="city-column"]')];
  let overflowing = 0;
  for (const c of cells) { const cb = c.getBoundingClientRect(); for (const ch of c.children) { const b = ch.getBoundingClientRect(); if (b.width && Math.max(cb.left - b.left, b.right - cb.right, cb.top - b.top, b.bottom - cb.bottom) > 0.5) overflowing++; } }
  const byHour = {};
  for (const c of cells) (byHour[c.dataset.refHour] ||= []).push(Math.round((c.dataset.axis === 'y' ? c.getBoundingClientRect().top : c.getBoundingClientRect().left) * 2) / 2);
  const misaligned = Object.values(byHour).filter((v) => new Set(v).size > 1).length;
  const c0 = cells[0].getBoundingClientRect();
  return { layout: rows ? 'desktop-rows' : 'mobile-columns', rows, cols: cols.length, cells: cells.length, axis: cells[0].dataset.axis,
    cell: [+c0.width.toFixed(1), +c0.height.toFixed(1)], overflowing, misalignedHours: misaligned,
    pageOverflowX: document.documentElement.scrollWidth > window.innerWidth,
    refInFirst: (rows ? document.querySelector('[data-testid="city-row"]') : cols[0]).textContent.includes('REF'),
    removeButtons: [...document.querySelectorAll('button')].filter((b) => /^Remove /.test(b.getAttribute('aria-label') || '')).length };
});
const out = {};
for (const [name, state] of [['three', three], ['six', six]]) {
  await page.evaluate((s) => localStorage.setItem('timezone-overlap:v1', JSON.stringify(s)), state);
  for (const w of [390, 767, 768, 900, 1024, 1440]) {
    await page.setViewportSize({ width: w, height: 900 });
    await page.reload();
    await page.waitForSelector('[data-testid="hour-cell"]');
    out[`${name}@${w}`] = await measure();
  }
}
out.errors = errors;
console.log(JSON.stringify(out));
EOF

